#nullable enable // autogenerated

using System.Linq;
using MVZ2.Resources;
using MVZ2Logic.Resources;
using PVZEngine;

namespace MVZ2.ResourcePacks
{
    public class ResourcePackCharacterModification : ITalkCharacterModification
    {
        public ResourcePackCharacterModification(ResourcePackCharacterModificationVariant[] variants)
        {
            Variants = variants;
        }

        public ModifiedCharacterSource Modify(ITalkCharacterSource source)
        {
            var srcVariants = source.GetVariants();
            var variants = new ITalkCharacterVariant[srcVariants.Length];
            for (int i = 0; i < variants.Length; i++)
            {
                var resultVariant = srcVariants[i];
                var modVariant = Variants.FirstOrDefault(v => v.ID == resultVariant.ID);
                if (modVariant != null)
                {
                    resultVariant = modVariant.Modify(resultVariant);
                }
                variants[i] = resultVariant;
            }
            var faceRight = FaceRight ?? source.FaceRight;
            return new ModifiedCharacterSource(variants, faceRight);
        }
        ITalkCharacterSource ITalkCharacterModification.Modify(ITalkCharacterSource source)
        {
            return Modify(source);
        }
        public bool? FaceRight { get; set; }
        public ResourcePackCharacterModificationVariant[] Variants { get; }
    }
    public class ResourcePackCharacterModificationVariant
    {
        public ResourcePackCharacterModificationVariant(NamespaceID id)
        {
            ID = id;
        }

        public ModifiedCharacterVariant Modify(ITalkCharacterVariant variant)
        {
            var id = variant.ID;

            ITalkCharacterLayer[] layers;
            if (Layers == null)
            {
                var srcLayers = variant.GetLayers();
                layers = new ITalkCharacterLayer[srcLayers.Length];
                for (int i = 0; i < layers.Length; i++)
                {
                    layers[i] = srcLayers[i];
                }
            }
            else
            {
                layers = new ITalkCharacterLayer[Layers.Length];
                for (int i = 0; i < layers.Length; i++)
                {
                    layers[i] = Layers[i].GetLayerSource();
                }
            }
            var width = Width ?? variant.Width;
            var height = Height ?? variant.Height;
            var pivotX = PivotX ?? variant.PivotX;
            var pivotY = PivotY ?? variant.PivotY;
            var unlock = variant.Unlock;
            var widthExtend = variant.WidthExtend;
            if (ExtendLeft.HasValue)
                widthExtend.x = ExtendLeft.Value;
            if (ExtendRight.HasValue)
                widthExtend.y = ExtendRight.Value;

            return new ModifiedCharacterVariant(id, layers)
            {
                Width = width,
                Height = height,
                PivotX = pivotX,
                PivotY = pivotY,
                Unlock = unlock,
                WidthExtend = widthExtend
            };
        }
        public NamespaceID ID { get; }
        public ResourcePackCharacterModificationLayer[]? Layers { get; set; }
        public int? Width { get; set; }
        public int? Height { get; set; }
        public float? PivotX { get; set; }
        public float? PivotY { get; set; }
        public float? ExtendLeft { get; set; }
        public float? ExtendRight { get; set; }
    }
    public class ResourcePackCharacterModificationLayer
    {
        public ResourcePackCharacterModificationLayer(SpriteReference sprite)
        {
            Sprite = sprite;
        }
        public ITalkCharacterLayer GetLayerSource()
        {
            return new ModifiedCharacterLayer(Sprite, PositionX, PositionY);
        }
        public SpriteReference Sprite { get; }
        public float PositionX { get; set; }
        public float PositionY { get; set; }
    }
}
